PRAGMA page_size=1024; BEGIN; CREATE TABLE t1(rowid INTEGER PRIMARY KEY, i INTEGER, t TEXT); WITH RECURSIVE seq(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM seq WHERE n<50000), data(n,x) AS (SELECT n, ((n*1103515245+12345)%2147483648)%50000 FROM seq) INSERT INTO t1 SELECT n,x,printf('n%05d',x) FROM data; CREATE INDEX i1 ON t1(t); UPDATE t1 SET i=i+1 WHERE rowid<10000; CREATE TABLE t5(t TEXT PRIMARY KEY, i INTEGER); INSERT OR IGNORE INTO t5 SELECT t,i FROM t1; COMMIT;